-- evt:test
RegisterEvent(7, nil, function(continueStep)
    if continueStep == 2 then
        XeenQuests.hook("m38.test_fire")
        evt.SetMonGroupBit(60, MonsterBits.Invisible, 0)
        SetValue(MapVar(1), 1)
        return
    end
    if continueStep ~= nil then
        return
    end
    if not ((not (IsQBitSet(QBit(111764)))) and (not (IsAtLeast(MapVar(1), 1)))) then
        return
    end
    evt.AskQuestion(7, 1, 0, 2, "Accept the test of Fire?", {"Yes", "Y"})
end, nil)

